    <script>
      const { createElement: h, useState } = React;

      function Header() {
        return h(
          "header",
          { className: "site-header page-shell" },
          h(
            "div",
            { className: "brand", "aria-label": "Acme Support" },
            h("span", { className: "brand-mark", "aria-hidden": "true" }, "A"),
            h("span", null, "Acme Support"),
          ),
        );
      }

      function FormField({
        id,
        label,
        type,
        name,
        autoComplete,
        required = false,
        helperText,
        placeholder,
      }) {
        const describedBy = helperText ? `${id}-helper` : undefined;

        return h(
          "div",
          { className: "form-field" },
          h(
            "label",
            { htmlFor: id },
            label,
            " ",
            required
              ? h("span", { className: "required-note" }, "(required)")
              : h("span", { className: "optional-note" }, "(optional)"),
          ),
          h("input", {
