        const [status, setStatus] = useState("");

        function handleSubmit(event) {
          event.preventDefault();
          const form = event.currentTarget;

          if (!form.checkValidity()) {
            form.reportValidity();
            return;
          }

          setStatus("Thanks. Your support request is ready to send.");
          form.reset();
        }

        return h(
          "section",
          { className: "card", "aria-labelledby": "contact-form-heading" },
          h(
            "div",
            { className: "card-header" },
            h("h2", { id: "contact-form-heading" }, "Contact support"),
            h(
              "p",
              null,
              "Tell us how to reach you and our team will follow up shortly.",
            ),
          ),
          h(
            "form",
            { className: "contact-form", noValidate: false, onSubmit: handleSubmit },
            h(FormField, {
              id: "full-name",
              label: "Full name",
              type: "text",
              name: "fullName",
              autoComplete: "name",
              required: true,
              placeholder: "Jamie Rivera",
            }),
            h(FormField, {
