              label: "Email address",
              type: "email",
              name: "email",
              autoComplete: "email",
              required: true,
              placeholder: "jamie@example.com",
            }),
            h(FormField, {
              id: "phone-number",
              label: "Phone number",
              type: "tel",
              name: "phone",
              autoComplete: "tel",
              helperText: "Use country code and area code when possible, for example +1 555 012 3456.",
              placeholder: "+1 555 012 3456",
            }),
            h("button", { className: "submit-button", type: "submit" }, "Submit request"),
            h(
              "p",
              { className: "status-message", "aria-live": "polite" },
              status,
            ),
          ),
        );
      }

