                h("li", null, h("strong", null, "Clear next steps"), "We route your issue to the right queue."),
                h("li", null, h("strong", null, "Secure handling"), "Your details are used only for support."),
              ),
            ),
            h(ContactForm),
          ),
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(h(App));
